include 'includes/init.php';$message=[];$stmt=$conn->prepare('SELECT FullName,Username,Email,Role,Status,CreatedAt FROM users WHERE id=?');$stmt->execute([$_SESSION['userId']]);$user=$stmt->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['FullName']??'');$username=trim($_POST['Username']??'');if($name===''||$username==='')$message=['Name and username are required.','danger'];else try{$data=[$name,$username];$sql='UPDATE users SET FullName=?,Username=?';if(!empty($_POST['password'])){if(strlen($_POST['password'])<10)throw new RuntimeException('New password must contain at least 10 characters.');$sql.=',Password=?';$data[]=password_hash($_POST['password'],PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$data[]=$_SESSION['userId'];$conn->prepare($sql)->execute($data);$_SESSION['name']=$name;audit('update','profile',(int)$_SESSION['userId']);$message=['Profile updated.','success'];$stmt->execute([$_SESSION['userId']]);$user=$stmt->fetch();}catch(Throwable $e){$message=[$e->getMessage(),'danger'];}}
?><div class="container-fluid"><h3 class="mb-4">My Profile</h3><div class="alerts"><?php if($message)showMessage($message);?></div><div class="card"><div class="card-body"><form method="post" style="max-width:700px"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><div class="mb-3"><label class="form-label">Full Name</label><input name="FullName" value="<?=escape($user['FullName'])?>" class="form-control" required></div><div class="mb-3"><label class="form-label">Username</label><input name="Username" value="<?=escape($user['Username'])?>" class="form-control" required></div><div class="mb-3"><label class="form-label">Email</label><input value="<?=escape($user['Email'])?>" class="form-control" disabled></div><div class="mb-3"><label class="form-label">Role</label><input value="<?=escape($user['Role'])?>" class="form-control" disabled></div><div class="mb-3"><label class="form-label">New Password (optional)</label><input type="password" name="password" minlength="10" class="form-control"></div><button class="btn btn-primary">Save Profile</button></form></div></div></div><?php include 'includes/footer.php';?>
